insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a1-10','en-a1-10',null,1,10,'published',1,'{"id":"en-a1-10","baseId":"en-a1-10","revision":1,"level":"A1","levelIndex":1,"order":10,"title":"Do va does: odatni tekshirish","objective":"Present Simpleda savol, inkor va qisqa javob tuzasiz.","context":"Kutubxona xodimi o‘quvchilarning o‘qish odatini so‘raydi.","prerequisites":["en-a1-09"],"minutes":25,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["I/you/we/they uchun do, he/she/it uchun does savol yordamchisidir. Does dan keyin asosiy fe’l -s olmaydi.","Don’t va doesn’t inkorni yasaydi: He doesn’t read comics. They don’t go by bus.","Do you read? — Yes, I do. Savolda to be emas, harakat fe’li bo‘lsa do/does ishlatiladi. Are you ready? esa boshqa tuzilma."],"pattern":"Do you read? / Does she read? / She doesn’t read.","examples":["Do you read every day?","Does Ali like comics?","He doesn’t read comics.","We don’t go by bus.","Yes, I do.","No, she doesn’t."],"vocabulary":[{"id":"en-a1-10-v0","term":"comic","meaning":"komiks","ipa":"/ˈkɒmɪk/","collocation":"read comics","example":"Does Ali like comics?"},{"id":"en-a1-10-v1","term":"often","meaning":"tez-tez","ipa":"/ˈɒfən/","collocation":"often read","example":"often read"},{"id":"en-a1-10-v2","term":"borrow","meaning":"qarzga olmoq","ipa":"/ˈbɒrəʊ/","collocation":"borrow a book","example":"Lola doesn’t borrow books every week because she has books at home."},{"id":"en-a1-10-v3","term":"week","meaning":"hafta","ipa":"/wiːk/","collocation":"every week","example":"He reads at the weekend."}],"visuals":[{"kind":"dialogue","title":"Ma’no va tuzilish","items":["Do you read? / Does she read? / She doesn’t read.","Do you read every day?","Does Ali like comics?"]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Kutubxona xodimi o‘quvchilarning o‘qish odatini so‘raydi.","He doesn’t read comics.","Yes, I do."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"We don’t go by bus.","audio":"/english-course/v7.23/en-a1-10-dictation.mp3"},"exercises":[{"id":"en-a1-10-choice","type":"choice","skill":"grammar","prompt":"He ___ read every day.","answers":["doesn’t"],"explanation":"Harakat fe’li va he uchun doesn’t.","hint":"Do you read? / Does she read? / She doesn’t read.","options":["doesn’t","don’t","isn’t"]},{"id":"en-a1-10-gap","type":"grammarFill","skill":"grammar","prompt":"___ she like comics?","answers":["Does"],"explanation":"I/you/we/they uchun do, he/she/it uchun does savol yordamchisidir. Does dan keyin asosiy fe’l -s olmaydi. Don’t va doesn’t inkorni yasaydi: He doesn’t read comics. They don’t go by bus. Do you read? — Yes, I do. Savolda to be emas, harakat fe’li bo‘lsa do/does ishlatiladi. Are you ready? esa boshqa tuzilma.","hint":"Do you read? / Does she read? / She doesn’t read."},{"id":"en-a1-10-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["Do you read every day?"],"explanation":"I/you/we/they uchun do, he/she/it uchun does savol yordamchisidir. Does dan keyin asosiy fe’l -s olmaydi. Don’t va doesn’t inkorni yasaydi: He doesn’t read comics. They don’t go by bus. Do you read? — Yes, I do. Savolda to be emas, harakat fe’li bo‘lsa do/does ishlatiladi. Are you ready? esa boshqa tuzilma.","hint":"Do you read? / Does she read? / She doesn’t read.","tokens":["Do","you","read","every","day?"]},{"id":"en-a1-10-fix","type":"correction","skill":"grammar","prompt":"Does Ali likes comics?","answers":["Does Ali like comics?"],"explanation":"I/you/we/they uchun do, he/she/it uchun does savol yordamchisidir. Does dan keyin asosiy fe’l -s olmaydi. Don’t va doesn’t inkorni yasaydi: He doesn’t read comics. They don’t go by bus. Do you read? — Yes, I do. Savolda to be emas, harakat fe’li bo‘lsa do/does ishlatiladi. Are you ready? esa boshqa tuzilma.","hint":"Do you read? / Does she read? / She doesn’t read."},{"id":"en-a1-10-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["komiks","tez-tez","qarzga olmoq","hafta"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"Do you read? / Does she read? / She doesn’t read.","left":["comic","often","borrow","week"],"options":["komiks","tez-tez","qarzga olmoq","hafta"]}],"reading":{"title":"Do va does: odatni tekshirish — vaziyat","text":"Our librarian asks students about reading. Lola reads every day, but Ali doesn’t. He reads at the weekend. Does he like comics? Yes, he does, but he also likes science books. Lola doesn’t borrow books every week because she has books at home. The librarian writes their answers and chooses new books for the school. The students don’t all enjoy the same stories.","sentences":["Our librarian asks students about reading.","Lola reads every day, but Ali doesn’t.","He reads at the weekend.","Does he like comics?","Yes, he does, but he also likes science books.","Lola doesn’t borrow books every week because she has books at home.","The librarian writes their answers and chooses new books for the school.","The students don’t all enjoy the same stories."],"questions":[{"id":"en-a1-10-reading0","type":"choice","skill":"reading","prompt":"Ali qachon o‘qiydi?","answers":["at the weekend"],"explanation":"He reads at the weekend.","hint":"Do you read? / Does she read? / She doesn’t read.","options":["at the weekend","every morning","every night"]},{"id":"en-a1-10-reading1","type":"choice","skill":"reading","prompt":"Lola nega har hafta kitob olmaydi?","answers":["she has books at home"],"explanation":"Because she has books at home — sabab.","hint":"Do you read? / Does she read? / She doesn’t read.","options":["she has books at home","she dislikes reading","the library is closed"]},{"id":"en-a1-10-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"Do you read? / Does she read? / She doesn’t read.","options":["Our librarian asks students about reading.","Lola reads every day, but Ali doesn’t.","He reads at the weekend.","Does he like comics?","Yes, he does, but he also likes science books.","Lola doesn’t borrow books every week because she has books at home.","The librarian writes their answers and chooses new books for the school.","The students don’t all enjoy the same stories."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"Do you read every day, Ali? No, I don’t. I read at the weekend. Does Lola borrow books every week? No, she doesn’t. She has books at home.","audio":"/english-course/v7.23/en-a1-10.mp3","synthetic":true,"questions":[{"id":"en-a1-10-listening0","type":"choice","skill":"listening","prompt":"Ali har kuni o‘qiydimi?","answers":["No"],"explanation":"No, I don’t deyiladi.","hint":"Do you read? / Does she read? / She doesn’t read.","options":["No","Yes","Only on Tuesday"]},{"id":"en-a1-10-listening1","type":"choice","skill":"listening","prompt":"Lolaning kitoblari qayerda?","answers":["at home"],"explanation":"She has books at home.","hint":"Do you read? / Does she read? / She doesn’t read.","options":["at home","at a shop","in a car"]},{"id":"en-a1-10-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["weekend","home"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"Do you read? / Does she read? / She doesn’t read.","rows":["Ali o‘qiydigan vaqt","Lola kitoblari bor joy"]},{"id":"en-a1-10-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["We don’t go by bus."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"Do you read? / Does she read? / She doesn’t read.","audio":"/english-course/v7.23/en-a1-10-dictation.mp3","transcript":"We don’t go by bus."}]},"writing":{"task":"Sherigingizning uch odati haqida savollar va javoblar yozing.","audience":"Sinfdagi sherigingiz","minWords":30,"maxWords":90,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"Do you read every day? Yes, I do. Does your brother read too? No, he doesn’t. He likes sport. We don’t borrow books every week, but we visit the library to study together.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["Do you read every day?","Does Ali like comics?","He doesn’t read comics."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Uchta Do you …? savol bering, javoblarni he/she bilan sinfga ayting.","seconds":35,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Sherigingizning uch odati haqida savollar va javoblar yozing.","exit":[[{"id":"en-a1-10-exit0","type":"grammarFill","skill":"grammar","prompt":"___ you read every week?","answers":["Do"],"explanation":"I/you/we/they uchun do, he/she/it uchun does savol yordamchisidir. Does dan keyin asosiy fe’l -s olmaydi. Don’t va doesn’t inkorni yasaydi: He doesn’t read comics. They don’t go by bus. Do you read? — Yes, I do. Savolda to be emas, harakat fe’li bo‘lsa do/does ishlatiladi. Are you ready? esa boshqa tuzilma.","hint":"Do you read? / Does she read? / She doesn’t read."},{"id":"en-a1-10-exit1","type":"grammarFill","skill":"grammar","prompt":"She doesn’t ___ comics.","answers":["read"],"explanation":"I/you/we/they uchun do, he/she/it uchun does savol yordamchisidir. Does dan keyin asosiy fe’l -s olmaydi. Don’t va doesn’t inkorni yasaydi: He doesn’t read comics. They don’t go by bus. Do you read? — Yes, I do. Savolda to be emas, harakat fe’li bo‘lsa do/does ishlatiladi. Are you ready? esa boshqa tuzilma.","hint":"Do you read? / Does she read? / She doesn’t read."},{"id":"en-a1-10-exit2","type":"grammarFill","skill":"grammar","prompt":"Does he like books? Yes, he ___.","answers":["does"],"explanation":"I/you/we/they uchun do, he/she/it uchun does savol yordamchisidir. Does dan keyin asosiy fe’l -s olmaydi. Don’t va doesn’t inkorni yasaydi: He doesn’t read comics. They don’t go by bus. Do you read? — Yes, I do. Savolda to be emas, harakat fe’li bo‘lsa do/does ishlatiladi. Are you ready? esa boshqa tuzilma.","hint":"Do you read? / Does she read? / She doesn’t read."},{"id":"en-a1-10-exit3","type":"choice","skill":"grammar","prompt":"To‘g‘ri savol qaysi?","answers":["Does Lola read?"],"explanation":"Does dan keyin asosiy shakl.","hint":"Do you read? / Does she read? / She doesn’t read.","options":["Does Lola read?","Does Lola reads?","Do Lola reads?"]},{"id":"en-a1-10-exit4","type":"choice","skill":"grammar","prompt":"They don’t ___ by bus.","answers":["go"],"explanation":"Don’t dan keyin go.","hint":"Do you read? / Does she read? / She doesn’t read.","options":["go","goes","going"]}],[{"id":"en-a1-10-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Does Ali like comics?"],"explanation":"I/you/we/they uchun do, he/she/it uchun does savol yordamchisidir. Does dan keyin asosiy fe’l -s olmaydi. Don’t va doesn’t inkorni yasaydi: He doesn’t read comics. They don’t go by bus. Do you read? — Yes, I do. Savolda to be emas, harakat fe’li bo‘lsa do/does ishlatiladi. Are you ready? esa boshqa tuzilma.","hint":"Do you read? / Does she read? / She doesn’t read.","tokens":["Does","Ali","like","comics?"]},{"id":"en-a1-10-exit-b1","type":"grammarFill","skill":"grammar","prompt":"She doesn’t ___ comics.","answers":["read"],"explanation":"I/you/we/they uchun do, he/she/it uchun does savol yordamchisidir. Does dan keyin asosiy fe’l -s olmaydi. Don’t va doesn’t inkorni yasaydi: He doesn’t read comics. They don’t go by bus. Do you read? — Yes, I do. Savolda to be emas, harakat fe’li bo‘lsa do/does ishlatiladi. Are you ready? esa boshqa tuzilma.","hint":"Do you read? / Does she read? / She doesn’t read."},{"id":"en-a1-10-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["We don’t go by bus."],"explanation":"I/you/we/they uchun do, he/she/it uchun does savol yordamchisidir. Does dan keyin asosiy fe’l -s olmaydi. Don’t va doesn’t inkorni yasaydi: He doesn’t read comics. They don’t go by bus. Do you read? — Yes, I do. Savolda to be emas, harakat fe’li bo‘lsa do/does ishlatiladi. Are you ready? esa boshqa tuzilma.","hint":"Do you read? / Does she read? / She doesn’t read.","tokens":["We","don’t","go","by","bus."]},{"id":"en-a1-10-exit-b3","type":"choice","skill":"grammar","prompt":"To‘g‘ri savol qaysi?","answers":["Does Lola read?"],"explanation":"Does dan keyin asosiy shakl.","hint":"Do you read? / Does she read? / She doesn’t read.","options":["Does Lola read?","Does Lola reads?","Do Lola reads?"]},{"id":"en-a1-10-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["No, she doesn’t."],"explanation":"I/you/we/they uchun do, he/she/it uchun does savol yordamchisidir. Does dan keyin asosiy fe’l -s olmaydi. Don’t va doesn’t inkorni yasaydi: He doesn’t read comics. They don’t go by bus. Do you read? — Yes, I do. Savolda to be emas, harakat fe’li bo‘lsa do/does ishlatiladi. Are you ready? esa boshqa tuzilma.","hint":"Do you read? / Does she read? / She doesn’t read.","tokens":["No,","she","doesn’t."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-a1-10","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-a1-10","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-a1-10","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-a1-10","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-a1-10","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-a1-10","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-a1-10","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-a1-10","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a1-11','en-a1-11',null,1,11,'published',1,'{"id":"en-a1-11","baseId":"en-a1-11","revision":1,"level":"A1","levelIndex":1,"order":11,"title":"Hozir nima bo‘lyapti? Present Continuous","objective":"Ayni paytdagi harakatni am/is/are + -ing bilan tasvirlaysiz.","context":"Sinf o‘quvchilari guruh loyiha ustida ishlamoqda.","prerequisites":["en-a1-10"],"minutes":25,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Present Continuous uchun am/is/are va fe’lning -ing shakli kerak: She is reading. Faqat reading yetarli emas.","Write → writing, sit → sitting kabi imlo o‘zgarishlariga e’tibor bering. Har fe’lni o‘zboshimchalik bilan bir xil o‘zgartirmang.","Savolda am/is/are oldinga chiqadi; inkorda not qo‘shiladi. Now va at the moment hozirgi jarayonni aniqlashtiradi."],"pattern":"Ega + am/is/are + verb-ing; Is she reading?","examples":["She is reading now.","I am writing a message.","They are making a poster.","Ali isn’t talking.","Are you listening?","We are sitting near the window."],"vocabulary":[{"id":"en-a1-11-v0","term":"poster","meaning":"plakat","ipa":"/ˈpəʊstə/","collocation":"make a poster","example":"They are making a poster."},{"id":"en-a1-11-v1","term":"message","meaning":"xabar","ipa":"/ˈmesɪdʒ/","collocation":"write a message","example":"I am writing a message."},{"id":"en-a1-11-v2","term":"at the moment","meaning":"hozirgi paytda","ipa":"/æt ðə ˈməʊmənt/","collocation":"work at the moment","example":"work at the moment"},{"id":"en-a1-11-v3","term":"make","meaning":"yasamoq","ipa":"/meɪk/","collocation":"make a model","example":"make a model"}],"visuals":[{"kind":"timeline","title":"Ma’no va tuzilish","items":["Ega + am/is/are + verb-ing; Is she reading?","She is reading now.","I am writing a message."],"timeline":[{"why":"Is reading hozir davom etayotgan jarayonni ko‘rsatadi. Qachon tugashi aytilmagan.","events":[{"kind":"span","from":260,"to":380,"label":"Jarayon hozirni qamraydi"}]},{"why":"Am writing shu vaziyatdagi jarayon. Chiziq uning aniq necha daqiqa davom etishini bildirmaydi.","events":[{"kind":"span","from":260,"to":380,"label":"Hozir yozish jarayoni"}]}]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Sinf o‘quvchilari guruh loyiha ustida ishlamoqda.","They are making a poster.","Are you listening?"]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"Ali isn’t talking.","audio":"/english-course/v7.23/en-a1-11-dictation.mp3"},"exercises":[{"id":"en-a1-11-choice","type":"choice","skill":"grammar","prompt":"Hozirgi harakatni tanlang.","answers":["I am reading now."],"explanation":"Now va am reading hozirgi jarayon.","hint":"Ega + am/is/are + verb-ing; Is she reading?","options":["I am reading now.","I read every day.","I read yesterday."]},{"id":"en-a1-11-gap","type":"grammarFill","skill":"grammar","prompt":"She is ___ a message. (write)","answers":["writing"],"explanation":"Present Continuous uchun am/is/are va fe’lning -ing shakli kerak: She is reading. Faqat reading yetarli emas. Write → writing, sit → sitting kabi imlo o‘zgarishlariga e’tibor bering. Har fe’lni o‘zboshimchalik bilan bir xil o‘zgartirmang. Savolda am/is/are oldinga chiqadi; inkorda not qo‘shiladi. Now va at the moment hozirgi jarayonni aniqlashtiradi.","hint":"Ega + am/is/are + verb-ing; Is she reading?"},{"id":"en-a1-11-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["She is reading now."],"explanation":"Present Continuous uchun am/is/are va fe’lning -ing shakli kerak: She is reading. Faqat reading yetarli emas. Write → writing, sit → sitting kabi imlo o‘zgarishlariga e’tibor bering. Har fe’lni o‘zboshimchalik bilan bir xil o‘zgartirmang. Savolda am/is/are oldinga chiqadi; inkorda not qo‘shiladi. Now va at the moment hozirgi jarayonni aniqlashtiradi.","hint":"Ega + am/is/are + verb-ing; Is she reading?","tokens":["She","is","reading","now."]},{"id":"en-a1-11-fix","type":"correction","skill":"grammar","prompt":"They making a poster.","answers":["They are making a poster."],"explanation":"Present Continuous uchun am/is/are va fe’lning -ing shakli kerak: She is reading. Faqat reading yetarli emas. Write → writing, sit → sitting kabi imlo o‘zgarishlariga e’tibor bering. Har fe’lni o‘zboshimchalik bilan bir xil o‘zgartirmang. Savolda am/is/are oldinga chiqadi; inkorda not qo‘shiladi. Now va at the moment hozirgi jarayonni aniqlashtiradi.","hint":"Ega + am/is/are + verb-ing; Is she reading?"},{"id":"en-a1-11-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["plakat","xabar","hozirgi paytda","yasamoq"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"Ega + am/is/are + verb-ing; Is she reading?","left":["poster","message","at the moment","make"],"options":["plakat","xabar","hozirgi paytda","yasamoq"]}],"reading":{"title":"Hozir nima bo‘lyapti? Present Continuous — vaziyat","text":"The students are working on a project now. Lola is reading information about birds. Ali is drawing a picture. Two students are making a poster, and the teacher is writing a title on the board. I am sitting near the window and checking our list. We are not playing games. Everyone is doing a different job, but we are making one project together.","sentences":["The students are working on a project now.","Lola is reading information about birds.","Ali is drawing a picture.","Two students are making a poster, and the teacher is writing a title on the board.","I am sitting near the window and checking our list.","We are not playing games.","Everyone is doing a different job, but we are making one project together."],"questions":[{"id":"en-a1-11-reading0","type":"choice","skill":"reading","prompt":"Ali nima qilyapti?","answers":["drawing a picture"],"explanation":"Ali is drawing a picture.","hint":"Ega + am/is/are + verb-ing; Is she reading?","options":["drawing a picture","reading a book","playing a game"]},{"id":"en-a1-11-reading1","type":"choice","skill":"reading","prompt":"Barcha o‘quvchilar bir xil ish qilyaptimi?","answers":["No"],"explanation":"Everyone is doing a different job.","hint":"Ega + am/is/are + verb-ing; Is she reading?","options":["No","Yes","They are all drawing"]},{"id":"en-a1-11-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"Ega + am/is/are + verb-ing; Is she reading?","options":["The students are working on a project now.","Lola is reading information about birds.","Ali is drawing a picture.","Two students are making a poster, and the teacher is writing a title on the board.","I am sitting near the window and checking our list.","We are not playing games.","Everyone is doing a different job, but we are making one project together."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"We are making a poster now. Lola is reading, and Ali is drawing. I am writing the title. The teacher isn’t talking. She is looking at our work.","audio":"/english-course/v7.23/en-a1-11.mp3","synthetic":true,"questions":[{"id":"en-a1-11-listening0","type":"choice","skill":"listening","prompt":"So‘zlovchi nima qilyapti?","answers":["writing the title"],"explanation":"I am writing the title.","hint":"Ega + am/is/are + verb-ing; Is she reading?","options":["writing the title","drawing a bird","playing"]},{"id":"en-a1-11-listening1","type":"choice","skill":"listening","prompt":"Ustoz nima qilyapti?","answers":["looking at the work"],"explanation":"She is looking at our work.","hint":"Ega + am/is/are + verb-ing; Is she reading?","options":["looking at the work","talking","leaving"]},{"id":"en-a1-11-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["drawing","reading"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"Ega + am/is/are + verb-ing; Is she reading?","rows":["Ali","Lola"]},{"id":"en-a1-11-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["Ali isn’t talking."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"Ega + am/is/are + verb-ing; Is she reading?","audio":"/english-course/v7.23/en-a1-11-dictation.mp3","transcript":"Ali isn’t talking."}]},"writing":{"task":"Hozir xonada uch kishi nima qilayotganini tasvirlang.","audience":"Sinfdagi sherigingiz","minWords":30,"maxWords":90,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"We are working in the library now. Lola is reading a science book. Ali is writing new words. I am making a small poster. We are not talking loudly because other students are studying nearby.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["She is reading now.","I am writing a message.","They are making a poster."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Jonli yoki xayoliy sinf sahnasini am/is/are + -ing bilan sharhlang.","seconds":35,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Hozir xonada uch kishi nima qilayotganini tasvirlang.","exit":[[{"id":"en-a1-11-exit0","type":"grammarFill","skill":"grammar","prompt":"I ___ writing.","answers":["am"],"explanation":"Present Continuous uchun am/is/are va fe’lning -ing shakli kerak: She is reading. Faqat reading yetarli emas. Write → writing, sit → sitting kabi imlo o‘zgarishlariga e’tibor bering. Har fe’lni o‘zboshimchalik bilan bir xil o‘zgartirmang. Savolda am/is/are oldinga chiqadi; inkorda not qo‘shiladi. Now va at the moment hozirgi jarayonni aniqlashtiradi.","hint":"Ega + am/is/are + verb-ing; Is she reading?"},{"id":"en-a1-11-exit1","type":"grammarFill","skill":"grammar","prompt":"They are ___ near the window. (sit)","answers":["sitting"],"explanation":"Present Continuous uchun am/is/are va fe’lning -ing shakli kerak: She is reading. Faqat reading yetarli emas. Write → writing, sit → sitting kabi imlo o‘zgarishlariga e’tibor bering. Har fe’lni o‘zboshimchalik bilan bir xil o‘zgartirmang. Savolda am/is/are oldinga chiqadi; inkorda not qo‘shiladi. Now va at the moment hozirgi jarayonni aniqlashtiradi.","hint":"Ega + am/is/are + verb-ing; Is she reading?"},{"id":"en-a1-11-exit2","type":"grammarFill","skill":"grammar","prompt":"___ she reading now?","answers":["Is"],"explanation":"Present Continuous uchun am/is/are va fe’lning -ing shakli kerak: She is reading. Faqat reading yetarli emas. Write → writing, sit → sitting kabi imlo o‘zgarishlariga e’tibor bering. Har fe’lni o‘zboshimchalik bilan bir xil o‘zgartirmang. Savolda am/is/are oldinga chiqadi; inkorda not qo‘shiladi. Now va at the moment hozirgi jarayonni aniqlashtiradi.","hint":"Ega + am/is/are + verb-ing; Is she reading?"},{"id":"en-a1-11-exit3","type":"choice","skill":"grammar","prompt":"Write ning -ing shakli qaysi?","answers":["writing"],"explanation":"Oxirgi e tushadi.","hint":"Ega + am/is/are + verb-ing; Is she reading?","options":["writing","writeing","writting"]},{"id":"en-a1-11-exit4","type":"choice","skill":"grammar","prompt":"We ___ playing games. (inkor)","answers":["aren’t"],"explanation":"We + are not.","hint":"Ega + am/is/are + verb-ing; Is she reading?","options":["aren’t","isn’t","don’t"]}],[{"id":"en-a1-11-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["I am writing a message."],"explanation":"Present Continuous uchun am/is/are va fe’lning -ing shakli kerak: She is reading. Faqat reading yetarli emas. Write → writing, sit → sitting kabi imlo o‘zgarishlariga e’tibor bering. Har fe’lni o‘zboshimchalik bilan bir xil o‘zgartirmang. Savolda am/is/are oldinga chiqadi; inkorda not qo‘shiladi. Now va at the moment hozirgi jarayonni aniqlashtiradi.","hint":"Ega + am/is/are + verb-ing; Is she reading?","tokens":["I","am","writing","a","message."]},{"id":"en-a1-11-exit-b1","type":"grammarFill","skill":"grammar","prompt":"They are ___ near the window. (sit)","answers":["sitting"],"explanation":"Present Continuous uchun am/is/are va fe’lning -ing shakli kerak: She is reading. Faqat reading yetarli emas. Write → writing, sit → sitting kabi imlo o‘zgarishlariga e’tibor bering. Har fe’lni o‘zboshimchalik bilan bir xil o‘zgartirmang. Savolda am/is/are oldinga chiqadi; inkorda not qo‘shiladi. Now va at the moment hozirgi jarayonni aniqlashtiradi.","hint":"Ega + am/is/are + verb-ing; Is she reading?"},{"id":"en-a1-11-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Ali isn’t talking."],"explanation":"Present Continuous uchun am/is/are va fe’lning -ing shakli kerak: She is reading. Faqat reading yetarli emas. Write → writing, sit → sitting kabi imlo o‘zgarishlariga e’tibor bering. Har fe’lni o‘zboshimchalik bilan bir xil o‘zgartirmang. Savolda am/is/are oldinga chiqadi; inkorda not qo‘shiladi. Now va at the moment hozirgi jarayonni aniqlashtiradi.","hint":"Ega + am/is/are + verb-ing; Is she reading?","tokens":["Ali","isn’t","talking."]},{"id":"en-a1-11-exit-b3","type":"choice","skill":"grammar","prompt":"Write ning -ing shakli qaysi?","answers":["writing"],"explanation":"Oxirgi e tushadi.","hint":"Ega + am/is/are + verb-ing; Is she reading?","options":["writing","writeing","writting"]},{"id":"en-a1-11-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["We are sitting near the window."],"explanation":"Present Continuous uchun am/is/are va fe’lning -ing shakli kerak: She is reading. Faqat reading yetarli emas. Write → writing, sit → sitting kabi imlo o‘zgarishlariga e’tibor bering. Har fe’lni o‘zboshimchalik bilan bir xil o‘zgartirmang. Savolda am/is/are oldinga chiqadi; inkorda not qo‘shiladi. Now va at the moment hozirgi jarayonni aniqlashtiradi.","hint":"Ega + am/is/are + verb-ing; Is she reading?","tokens":["We","are","sitting","near","the","window."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-a1-11","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-a1-11","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-a1-11","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-a1-11","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-a1-11","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-a1-11","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-a1-11","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-a1-11","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a1-12','en-a1-12',null,1,12,'published',1,'{"id":"en-a1-12","baseId":"en-a1-12","revision":1,"level":"A1","levelIndex":1,"order":12,"title":"Odatmi yoki hozirgi harakatmi?","objective":"Present Simple va Present Continuousni ma’noga qarab tanlaysiz.","context":"Odatda avtobusda yuradigan Ali bugun piyoda ketmoqda.","prerequisites":["en-a1-11"],"minutes":25,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Muntazam odat uchun Present Simple, ayni vaqt yoki vaqtinchalik jarayon uchun Present Continuousni ishlating.","Usually she walks, but today she is taking the bus — ikki shakl ikki xil vazifani bajaradi. Signal so‘z ma’noni tushunishga yordam beradi, uni yolg‘iz qoida deb olmang.","Know, like, want kabi holat fe’llari ko‘pincha oddiy shaklda ishlatiladi: I know, I like. I am knowing standart qo‘llanish emas."],"pattern":"Usually I walk. Today I am taking the bus. / I like …","examples":["I usually walk to school.","Today I am taking the bus.","Lola reads every evening.","She is reading now.","I know the answer.","They are studying for a test this week."],"vocabulary":[{"id":"en-a1-12-v0","term":"usually","meaning":"odatda","ipa":"/ˈjuːʒuəli/","collocation":"usually walk","example":"I usually walk to school."},{"id":"en-a1-12-v1","term":"take the bus","meaning":"avtobusda bormoq","ipa":"/teɪk ðə bʌs/","collocation":"take the bus today","example":"take the bus today"},{"id":"en-a1-12-v2","term":"answer","meaning":"javob","ipa":"/ˈɑːnsə/","collocation":"know the answer","example":"I know the answer."},{"id":"en-a1-12-v3","term":"this week","meaning":"shu hafta","ipa":"/ðɪs wiːk/","collocation":"study this week","example":"They are studying for a test this week."}],"visuals":[{"kind":"compare","title":"Ma’no va tuzilish","items":["Usually I walk. Today I am taking the bus. / I like …","I usually walk to school.","Today I am taking the bus."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Odatda avtobusda yuradigan Ali bugun piyoda ketmoqda.","Lola reads every evening.","I know the answer."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"She is reading now.","audio":"/english-course/v7.23/en-a1-12-dictation.mp3"},"exercises":[{"id":"en-a1-12-choice","type":"choice","skill":"grammar","prompt":"Ayni paytda o‘qiyotgan Lola haqida gap tanlang.","answers":["She is reading now."],"explanation":"Continuous hozirgi jarayonni ko‘rsatadi.","hint":"Usually I walk. Today I am taking the bus. / I like …","options":["She is reading now.","She reads every day.","She read yesterday."]},{"id":"en-a1-12-gap","type":"grammarFill","skill":"grammar","prompt":"She usually ___ a story. (read)","answers":["reads"],"explanation":"Muntazam odat uchun Present Simple, ayni vaqt yoki vaqtinchalik jarayon uchun Present Continuousni ishlating. Usually she walks, but today she is taking the bus — ikki shakl ikki xil vazifani bajaradi. Signal so‘z ma’noni tushunishga yordam beradi, uni yolg‘iz qoida deb olmang. Know, like, want kabi holat fe’llari ko‘pincha oddiy shaklda ishlatiladi: I know, I like. I am knowing standart qo‘llanish emas.","hint":"Usually I walk. Today I am taking the bus. / I like …"},{"id":"en-a1-12-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["I usually walk to school."],"explanation":"Muntazam odat uchun Present Simple, ayni vaqt yoki vaqtinchalik jarayon uchun Present Continuousni ishlating. Usually she walks, but today she is taking the bus — ikki shakl ikki xil vazifani bajaradi. Signal so‘z ma’noni tushunishga yordam beradi, uni yolg‘iz qoida deb olmang. Know, like, want kabi holat fe’llari ko‘pincha oddiy shaklda ishlatiladi: I know, I like. I am knowing standart qo‘llanish emas.","hint":"Usually I walk. Today I am taking the bus. / I like …","tokens":["I","usually","walk","to","school."]},{"id":"en-a1-12-fix","type":"correction","skill":"grammar","prompt":"I am knowing the answer.","answers":["I know the answer."],"explanation":"Muntazam odat uchun Present Simple, ayni vaqt yoki vaqtinchalik jarayon uchun Present Continuousni ishlating. Usually she walks, but today she is taking the bus — ikki shakl ikki xil vazifani bajaradi. Signal so‘z ma’noni tushunishga yordam beradi, uni yolg‘iz qoida deb olmang. Know, like, want kabi holat fe’llari ko‘pincha oddiy shaklda ishlatiladi: I know, I like. I am knowing standart qo‘llanish emas.","hint":"Usually I walk. Today I am taking the bus. / I like …"},{"id":"en-a1-12-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["odatda","avtobusda bormoq","javob","shu hafta"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"Usually I walk. Today I am taking the bus. / I like …","left":["usually","take the bus","answer","this week"],"options":["odatda","avtobusda bormoq","javob","shu hafta"]},{"id":"en-a1-12-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["usually","take the bus","answer","this week"],"options":["usually walk","take the bus today","know the answer","study this week"],"answers":["usually walk","take the bus today","know the answer","study this week"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."},{"id":"en-a1-12-dialogue","type":"dialogue","skill":"grammar","prompt":"Sherik: “Can you give one example?” Siz: darsdagi birinchi namunani qayta tuzing.","answers":["I usually walk to school."],"tokens":["I","usually","walk","to","school."],"hint":"Usually I walk. Today I am taking the bus. / I like …","explanation":"Muntazam odat uchun Present Simple, ayni vaqt yoki vaqtinchalik jarayon uchun Present Continuousni ishlating."},{"id":"en-a1-12-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Present Simple: odatlar va kun tartibi: He ___ in a shop.","answers":["works"],"explanation":"He uchun fe’lga -s qo‘shiladi.","hint":"I go / she goes; I study / he studies; every day","options":["works","work","working"],"recap":true,"sourceLesson":"Present Simple: odatlar va kun tartibi"},{"id":"en-a1-12-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Do va does: odatni tekshirish: He ___ read every day.","answers":["doesn’t"],"explanation":"Harakat fe’li va he uchun doesn’t.","hint":"Do you read? / Does she read? / She doesn’t read.","options":["doesn’t","don’t","isn’t"],"recap":true,"sourceLesson":"Do va does: odatni tekshirish"},{"id":"en-a1-12-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Hozir nima bo‘lyapti? Present Continuous: Hozirgi harakatni tanlang.","answers":["I am reading now."],"explanation":"Now va am reading hozirgi jarayon.","hint":"Ega + am/is/are + verb-ing; Is she reading?","options":["I am reading now.","I read every day.","I read yesterday."],"recap":true,"sourceLesson":"Hozir nima bo‘lyapti? Present Continuous"}],"reading":{"title":"Odatmi yoki hozirgi harakatmi? — vaziyat","text":"Ali usually takes the bus to school. Today he is walking because the weather is good. Lola reads a story every evening, but this evening she is studying for a science test. They both like English. At the moment, they are discussing their homework. Ali knows the answer to the first question, and Lola is looking for the second answer in her book.","sentences":["Ali usually takes the bus to school.","Today he is walking because the weather is good.","Lola reads a story every evening, but this evening she is studying for a science test.","They both like English.","At the moment, they are discussing their homework.","Ali knows the answer to the first question, and Lola is looking for the second answer in her book."],"questions":[{"id":"en-a1-12-reading0","type":"choice","skill":"reading","prompt":"Ali bugun nega piyoda ketyapti?","answers":["the weather is good"],"explanation":"Because the weather is good — matndagi sabab.","hint":"Usually I walk. Today I am taking the bus. / I like …","options":["the weather is good","the bus is broken","he is late"]},{"id":"en-a1-12-reading1","type":"choice","skill":"reading","prompt":"Lola odatda kechqurun nima qiladi?","answers":["reads a story"],"explanation":"Reads a story every evening — odat.","hint":"Usually I walk. Today I am taking the bus. / I like …","options":["reads a story","studies science every night","takes a bus"]},{"id":"en-a1-12-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"Usually I walk. Today I am taking the bus. / I like …","options":["Ali usually takes the bus to school.","Today he is walking because the weather is good.","Lola reads a story every evening, but this evening she is studying for a science test.","They both like English.","At the moment, they are discussing their homework.","Ali knows the answer to the first question, and Lola is looking for the second answer in her book."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"I usually go by bus, but today I am walking. Lola usually reads in the evening. Today she is studying for a test. I know the first answer, but I need help with the second.","audio":"/english-course/v7.23/en-a1-12.mp3","synthetic":true,"questions":[{"id":"en-a1-12-listening0","type":"choice","skill":"listening","prompt":"So‘zlovchi bugun qanday ketyapti?","answers":["walking"],"explanation":"Today I am walking.","hint":"Usually I walk. Today I am taking the bus. / I like …","options":["walking","by bus","by train"]},{"id":"en-a1-12-listening1","type":"choice","skill":"listening","prompt":"Qaysi javobni biladi?","answers":["the first"],"explanation":"I know the first answer.","hint":"Usually I walk. Today I am taking the bus. / I like …","options":["the first","the second","both"]},{"id":"en-a1-12-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["walking","studying"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"Usually I walk. Today I am taking the bus. / I like …","rows":["Bugungi yo‘l","Lolaning bugungi ishi"]},{"id":"en-a1-12-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["She is reading now."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"Usually I walk. Today I am taking the bus. / I like …","audio":"/english-course/v7.23/en-a1-12-dictation.mp3","transcript":"She is reading now."}]},"writing":{"task":"Odatiy kuningiz bilan bugungi kuningizning ikki farqini yozing.","audience":"Sinfdagi sherigingiz","minWords":30,"maxWords":90,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"I usually walk to school, but today I am taking the bus. I read after dinner every evening. Tonight I am making a poster for class. I like our project, and I know the topic well.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["I usually walk to school.","Today I am taking the bus.","Lola reads every evening."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Usually … but today … tuzilmasi bilan ikki taqqoslash ayting.","seconds":35,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Odatiy kuningiz bilan bugungi kuningizning ikki farqini yozing.","exit":[[{"id":"en-a1-12-exit0","type":"grammarFill","skill":"grammar","prompt":"They ___ studying now.","answers":["are"],"explanation":"Muntazam odat uchun Present Simple, ayni vaqt yoki vaqtinchalik jarayon uchun Present Continuousni ishlating. Usually she walks, but today she is taking the bus — ikki shakl ikki xil vazifani bajaradi. Signal so‘z ma’noni tushunishga yordam beradi, uni yolg‘iz qoida deb olmang. Know, like, want kabi holat fe’llari ko‘pincha oddiy shaklda ishlatiladi: I know, I like. I am knowing standart qo‘llanish emas.","hint":"Usually I walk. Today I am taking the bus. / I like …"},{"id":"en-a1-12-exit1","type":"grammarFill","skill":"grammar","prompt":"He usually ___ by bus. (go)","answers":["goes"],"explanation":"Muntazam odat uchun Present Simple, ayni vaqt yoki vaqtinchalik jarayon uchun Present Continuousni ishlating. Usually she walks, but today she is taking the bus — ikki shakl ikki xil vazifani bajaradi. Signal so‘z ma’noni tushunishga yordam beradi, uni yolg‘iz qoida deb olmang. Know, like, want kabi holat fe’llari ko‘pincha oddiy shaklda ishlatiladi: I know, I like. I am knowing standart qo‘llanish emas.","hint":"Usually I walk. Today I am taking the bus. / I like …"},{"id":"en-a1-12-exit2","type":"grammarFill","skill":"grammar","prompt":"I ___ the answer. (know)","answers":["know"],"explanation":"Muntazam odat uchun Present Simple, ayni vaqt yoki vaqtinchalik jarayon uchun Present Continuousni ishlating. Usually she walks, but today she is taking the bus — ikki shakl ikki xil vazifani bajaradi. Signal so‘z ma’noni tushunishga yordam beradi, uni yolg‘iz qoida deb olmang. Know, like, want kabi holat fe’llari ko‘pincha oddiy shaklda ishlatiladi: I know, I like. I am knowing standart qo‘llanish emas.","hint":"Usually I walk. Today I am taking the bus. / I like …"},{"id":"en-a1-12-exit3","type":"choice","skill":"grammar","prompt":"Odatga mos shaklni tanlang.","answers":["She works every day."],"explanation":"Muntazam odatda works.","hint":"Usually I walk. Today I am taking the bus. / I like …","options":["She works every day.","She is work every day.","She working every day."]},{"id":"en-a1-12-exit4","type":"choice","skill":"grammar","prompt":"Today vaqtinchalik harakatga mos gap qaysi?","answers":["I am walking today."],"explanation":"Am + -ing.","hint":"Usually I walk. Today I am taking the bus. / I like …","options":["I am walking today.","I walking today.","I am walk today."]}],[{"id":"en-a1-12-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Today I am taking the bus."],"explanation":"Muntazam odat uchun Present Simple, ayni vaqt yoki vaqtinchalik jarayon uchun Present Continuousni ishlating. Usually she walks, but today she is taking the bus — ikki shakl ikki xil vazifani bajaradi. Signal so‘z ma’noni tushunishga yordam beradi, uni yolg‘iz qoida deb olmang. Know, like, want kabi holat fe’llari ko‘pincha oddiy shaklda ishlatiladi: I know, I like. I am knowing standart qo‘llanish emas.","hint":"Usually I walk. Today I am taking the bus. / I like …","tokens":["Today","I","am","taking","the","bus."]},{"id":"en-a1-12-exit-b1","type":"grammarFill","skill":"grammar","prompt":"He usually ___ by bus. (go)","answers":["goes"],"explanation":"Muntazam odat uchun Present Simple, ayni vaqt yoki vaqtinchalik jarayon uchun Present Continuousni ishlating. Usually she walks, but today she is taking the bus — ikki shakl ikki xil vazifani bajaradi. Signal so‘z ma’noni tushunishga yordam beradi, uni yolg‘iz qoida deb olmang. Know, like, want kabi holat fe’llari ko‘pincha oddiy shaklda ishlatiladi: I know, I like. I am knowing standart qo‘llanish emas.","hint":"Usually I walk. Today I am taking the bus. / I like …"},{"id":"en-a1-12-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["She is reading now."],"explanation":"Muntazam odat uchun Present Simple, ayni vaqt yoki vaqtinchalik jarayon uchun Present Continuousni ishlating. Usually she walks, but today she is taking the bus — ikki shakl ikki xil vazifani bajaradi. Signal so‘z ma’noni tushunishga yordam beradi, uni yolg‘iz qoida deb olmang. Know, like, want kabi holat fe’llari ko‘pincha oddiy shaklda ishlatiladi: I know, I like. I am knowing standart qo‘llanish emas.","hint":"Usually I walk. Today I am taking the bus. / I like …","tokens":["She","is","reading","now."]},{"id":"en-a1-12-exit-b3","type":"choice","skill":"grammar","prompt":"Odatga mos shaklni tanlang.","answers":["She works every day."],"explanation":"Muntazam odatda works.","hint":"Usually I walk. Today I am taking the bus. / I like …","options":["She works every day.","She is work every day.","She working every day."]},{"id":"en-a1-12-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["They are studying for a test this week."],"explanation":"Muntazam odat uchun Present Simple, ayni vaqt yoki vaqtinchalik jarayon uchun Present Continuousni ishlating. Usually she walks, but today she is taking the bus — ikki shakl ikki xil vazifani bajaradi. Signal so‘z ma’noni tushunishga yordam beradi, uni yolg‘iz qoida deb olmang. Know, like, want kabi holat fe’llari ko‘pincha oddiy shaklda ishlatiladi: I know, I like. I am knowing standart qo‘llanish emas.","hint":"Usually I walk. Today I am taking the bus. / I like …","tokens":["They","are","studying","for","a","test","this","week."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-e