B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-a1-12","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-a1-12","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-a1-12","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied.","recapQuestions":[{"id":"en-a1-12-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Present Simple: odatlar va kun tartibi: He ___ in a shop.","answers":["works"],"explanation":"He uchun fe’lga -s qo‘shiladi.","hint":"I go / she goes; I study / he studies; every day","options":["works","work","working"],"recap":true,"sourceLesson":"Present Simple: odatlar va kun tartibi"},{"id":"en-a1-12-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Do va does: odatni tekshirish: He ___ read every day.","answers":["doesn’t"],"explanation":"Harakat fe’li va he uchun doesn’t.","hint":"Do you read? / Does she read? / She doesn’t read.","options":["doesn’t","don’t","isn’t"],"recap":true,"sourceLesson":"Do va does: odatni tekshirish"},{"id":"en-a1-12-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Hozir nima bo‘lyapti? Present Continuous: Hozirgi harakatni tanlang.","answers":["I am reading now."],"explanation":"Now va am reading hozirgi jarayon.","hint":"Ega + am/is/are + verb-ing; Is she reading?","options":["I am reading now.","I read every day.","I read yesterday."],"recap":true,"sourceLesson":"Hozir nima bo‘lyapti? Present Continuous"}]}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a1-13','en-a1-13',null,1,13,'published',1,'{"id":"en-a1-13","baseId":"en-a1-13","revision":1,"level":"A1","levelIndex":1,"order":13,"title":"Savol so‘zlari: kim, nima, qayer, qachon?","objective":"Kerakli ma’lumot uchun mos savol so‘zini tanlaysiz.","context":"Yangi to‘garak haqida do‘stingizdan batafsil so‘raysiz.","prerequisites":["en-a1-12"],"minutes":25,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Who odam, what narsa yoki ish, where joy, when vaqt, why sabab, how usul yoki holat haqida so‘raydi.","To be bilan Where is the room? Harakat fe’li bilan Where do you study? Savol yordamchisini mavzuga mos tanlang.","How old, how many va what time bitta so‘z emas, birgalikdagi savol qoliplaridir. Why savoliga because bilan sabab aytish mumkin."],"pattern":"Where is …? / When do you …? / Why …? — Because …","examples":["Where is the library?","When do you study?","Who is your teacher?","What time does the club start?","Why do you like it?","How many students are there?"],"vocabulary":[{"id":"en-a1-13-v0","term":"when","meaning":"qachon","ipa":"/wen/","collocation":"when do you study","example":"When do you study?"},{"id":"en-a1-13-v1","term":"where","meaning":"qayerda","ipa":"/weə/","collocation":"where is the room","example":"Where is the library?"},{"id":"en-a1-13-v2","term":"why","meaning":"nega","ipa":"/waɪ/","collocation":"why do you like it","example":"Why do you like it?"},{"id":"en-a1-13-v3","term":"because","meaning":"chunki","ipa":"/bɪˈkɒz/","collocation":"because it is useful","example":"Lola likes it because she can draw with friends."}],"visuals":[{"kind":"map","title":"Ma’no va tuzilish","items":["Where is …? / When do you …? / Why …? — Because …","Where is the library?","When do you study?"]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Yangi to‘garak haqida do‘stingizdan batafsil so‘raysiz.","Who is your teacher?","Why do you like it?"]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"What time does the club start?","audio":"/english-course/v7.23/en-a1-13-dictation.mp3"},"exercises":[{"id":"en-a1-13-choice","type":"choice","skill":"grammar","prompt":"Sababni qaysi savol so‘raydi?","answers":["Why?"],"explanation":"Why sabab uchun.","hint":"Where is …? / When do you …? / Why …? — Because …","options":["Why?","Where?","When?"]},{"id":"en-a1-13-gap","type":"grammarFill","skill":"grammar","prompt":"___ is your teacher? (odam)","answers":["Who"],"explanation":"Who odam, what narsa yoki ish, where joy, when vaqt, why sabab, how usul yoki holat haqida so‘raydi. To be bilan Where is the room? Harakat fe’li bilan Where do you study? Savol yordamchisini mavzuga mos tanlang. How old, how many va what time bitta so‘z emas, birgalikdagi savol qoliplaridir. Why savoliga because bilan sabab aytish mumkin.","hint":"Where is …? / When do you …? / Why …? — Because …"},{"id":"en-a1-13-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["Where is the library?"],"explanation":"Who odam, what narsa yoki ish, where joy, when vaqt, why sabab, how usul yoki holat haqida so‘raydi. To be bilan Where is the room? Harakat fe’li bilan Where do you study? Savol yordamchisini mavzuga mos tanlang. How old, how many va what time bitta so‘z emas, birgalikdagi savol qoliplaridir. Why savoliga because bilan sabab aytish mumkin.","hint":"Where is …? / When do you …? / Why …? — Because …","tokens":["Where","is","the","library?"]},{"id":"en-a1-13-fix","type":"correction","skill":"grammar","prompt":"Where you study?","answers":["Where do you study?"],"explanation":"Who odam, what narsa yoki ish, where joy, when vaqt, why sabab, how usul yoki holat haqida so‘raydi. To be bilan Where is the room? Harakat fe’li bilan Where do you study? Savol yordamchisini mavzuga mos tanlang. How old, how many va what time bitta so‘z emas, birgalikdagi savol qoliplaridir. Why savoliga because bilan sabab aytish mumkin.","hint":"Where is …? / When do you …? / Why …? — Because …"},{"id":"en-a1-13-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["qachon","qayerda","nega","chunki"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"Where is …? / When do you …? / Why …? — Because …","left":["when","where","why","because"],"options":["qachon","qayerda","nega","chunki"]}],"reading":{"title":"Savol so‘zlari: kim, nima, qayer, qachon? — vaziyat","text":"Our new art club meets in Room 6. It starts at four o’clock on Friday. Malika is the teacher. There are twelve students in the club. Lola likes it because she can draw with friends. Ali asks where the room is and what time the club starts. He also asks who the teacher is. Lola gives him the information and invites him to the next meeting.","sentences":["Our new art club meets in Room 6.","It starts at four o’clock on Friday.","Malika is the teacher.","There are twelve students in the club.","Lola likes it because she can draw with friends.","Ali asks where the room is and what time the club starts.","He also asks who the teacher is.","Lola gives him the information and invites him to the next meeting."],"questions":[{"id":"en-a1-13-reading0","type":"choice","skill":"reading","prompt":"Mashg‘ulot nechada boshlanadi?","answers":["four o’clock"],"explanation":"It starts at four o’clock.","hint":"Where is …? / When do you …? / Why …? — Because …","options":["four o’clock","three o’clock","five o’clock"]},{"id":"en-a1-13-reading1","type":"choice","skill":"reading","prompt":"Lola nima uchun to‘garakni yoqtiradi?","answers":["she can draw with friends"],"explanation":"Because she can draw with friends.","hint":"Where is …? / When do you …? / Why …? — Because …","options":["she can draw with friends","it has computers","it is on Monday"]},{"id":"en-a1-13-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"Where is …? / When do you …? / Why …? — Because …","options":["Our new art club meets in Room 6.","It starts at four o’clock on Friday.","Malika is the teacher.","There are twelve students in the club.","Lola likes it because she can draw with friends.","Ali asks where the room is and what time the club starts.","He also asks who the teacher is.","Lola gives him the information and invites him to the next meeting."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"The art club is in Room 6. It starts at four on Friday. Our teacher is Malika. There are twelve students. I like the club because I can draw with friends.","audio":"/english-course/v7.23/en-a1-13.mp3","synthetic":true,"questions":[{"id":"en-a1-13-listening0","type":"choice","skill":"listening","prompt":"To‘garak qaysi xona?","answers":["6"],"explanation":"Room 6 deyiladi.","hint":"Where is …? / When do you …? / Why …? — Because …","options":["6","4","12"]},{"id":"en-a1-13-listening1","type":"choice","skill":"listening","prompt":"O‘qituvchi kim?","answers":["Malika"],"explanation":"Our teacher is Malika.","hint":"Where is …? / When do you …? / Why …? — Because …","options":["Malika","Ali","Lola"]},{"id":"en-a1-13-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["6","twelve"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"Where is …? / When do you …? / Why …? — Because …","rows":["Xona","O‘quvchilar soni"]},{"id":"en-a1-13-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["What time does the club start?"],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"Where is …? / When do you …? / Why …? — Because …","audio":"/english-course/v7.23/en-a1-13-dictation.mp3","transcript":"What time does the club start?"}]},"writing":{"task":"To‘garak e’loni uchun joy, vaqt, ustoz va sababni ko‘rsatadigan savol-javob yozing.","audience":"Sinfdagi sherigingiz","minWords":30,"maxWords":90,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"Where is our club? It is in Room 6. What time does it start? It starts at four on Friday. Who is the teacher? Malika is our teacher. I like it because I can draw with friends.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["Where is the library?","When do you study?","Who is your teacher?"],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"To‘garak bo‘yicha beshta turli savol so‘rang va sherigingizning javobini tekshiring.","seconds":35,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"To‘garak e’loni uchun joy, vaqt, ustoz va sababni ko‘rsatadigan savol-javob yozing.","exit":[[{"id":"en-a1-13-exit0","type":"grammarFill","skill":"grammar","prompt":"___ is the library? (joy)","answers":["Where"],"explanation":"Who odam, what narsa yoki ish, where joy, when vaqt, why sabab, how usul yoki holat haqida so‘raydi. To be bilan Where is the room? Harakat fe’li bilan Where do you study? Savol yordamchisini mavzuga mos tanlang. How old, how many va what time bitta so‘z emas, birgalikdagi savol qoliplaridir. Why savoliga because bilan sabab aytish mumkin.","hint":"Where is …? / When do you …? / Why …? — Because …"},{"id":"en-a1-13-exit1","type":"grammarFill","skill":"grammar","prompt":"___ does the club start? (qachon)","answers":["When"],"explanation":"Who odam, what narsa yoki ish, where joy, when vaqt, why sabab, how usul yoki holat haqida so‘raydi. To be bilan Where is the room? Harakat fe’li bilan Where do you study? Savol yordamchisini mavzuga mos tanlang. How old, how many va what time bitta so‘z emas, birgalikdagi savol qoliplaridir. Why savoliga because bilan sabab aytish mumkin.","hint":"Where is …? / When do you …? / Why …? — Because …"},{"id":"en-a1-13-exit2","type":"grammarFill","skill":"grammar","prompt":"___ many students are there?","answers":["How"],"explanation":"Who odam, what narsa yoki ish, where joy, when vaqt, why sabab, how usul yoki holat haqida so‘raydi. To be bilan Where is the room? Harakat fe’li bilan Where do you study? Savol yordamchisini mavzuga mos tanlang. How old, how many va what time bitta so‘z emas, birgalikdagi savol qoliplaridir. Why savoliga because bilan sabab aytish mumkin.","hint":"Where is …? / When do you …? / Why …? — Because …"},{"id":"en-a1-13-exit3","type":"choice","skill":"grammar","prompt":"What time nimani so‘raydi?","answers":["an exact time"],"explanation":"What time aniq soat uchun.","hint":"Where is …? / When do you …? / Why …? — Because …","options":["an exact time","a person","a reason"]},{"id":"en-a1-13-exit4","type":"choice","skill":"grammar","prompt":"Why savoliga mos boshlanishni tanlang.","answers":["Because it is useful."],"explanation":"Because sababni bog‘laydi.","hint":"Where is …? / When do you …? / Why …? — Because …","options":["Because it is useful.","At four.","In Room 6."]}],[{"id":"en-a1-13-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["When do you study?"],"explanation":"Who odam, what narsa yoki ish, where joy, when vaqt, why sabab, how usul yoki holat haqida so‘raydi. To be bilan Where is the room? Harakat fe’li bilan Where do you study? Savol yordamchisini mavzuga mos tanlang. How old, how many va what time bitta so‘z emas, birgalikdagi savol qoliplaridir. Why savoliga because bilan sabab aytish mumkin.","hint":"Where is …? / When do you …? / Why …? — Because …","tokens":["When","do","you","study?"]},{"id":"en-a1-13-exit-b1","type":"grammarFill","skill":"grammar","prompt":"___ does the club start? (qachon)","answers":["When"],"explanation":"Who odam, what narsa yoki ish, where joy, when vaqt, why sabab, how usul yoki holat haqida so‘raydi. To be bilan Where is the room? Harakat fe’li bilan Where do you study? Savol yordamchisini mavzuga mos tanlang. How old, how many va what time bitta so‘z emas, birgalikdagi savol qoliplaridir. Why savoliga because bilan sabab aytish mumkin.","hint":"Where is …? / When do you …? / Why …? — Because …"},{"id":"en-a1-13-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["What time does the club start?"],"explanation":"Who odam, what narsa yoki ish, where joy, when vaqt, why sabab, how usul yoki holat haqida so‘raydi. To be bilan Where is the room? Harakat fe’li bilan Where do you study? Savol yordamchisini mavzuga mos tanlang. How old, how many va what time bitta so‘z emas, birgalikdagi savol qoliplaridir. Why savoliga because bilan sabab aytish mumkin.","hint":"Where is …? / When do you …? / Why …? — Because …","tokens":["What","time","does","the","club","start?"]},{"id":"en-a1-13-exit-b3","type":"choice","skill":"grammar","prompt":"What time nimani so‘raydi?","answers":["an exact time"],"explanation":"What time aniq soat uchun.","hint":"Where is …? / When do you …? / Why …? — Because …","options":["an exact time","a person","a reason"]},{"id":"en-a1-13-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["How many students are there?"],"explanation":"Who odam, what narsa yoki ish, where joy, when vaqt, why sabab, how usul yoki holat haqida so‘raydi. To be bilan Where is the room? Harakat fe’li bilan Where do you study? Savol yordamchisini mavzuga mos tanlang. How old, how many va what time bitta so‘z emas, birgalikdagi savol qoliplaridir. Why savoliga because bilan sabab aytish mumkin.","hint":"Where is …? / When do you …? / Why …? — Because …","tokens":["How","many","students","are","there?"]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-a1-13","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-a1-13","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-a1-13","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-a1-13","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-a1-13","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-a1-13","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-a1-13","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-a1-13","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a1-14','en-a1-14',null,1,14,'published',1,'{"id":"en-a1-14","baseId":"en-a1-14","revision":1,"level":"A1","levelIndex":1,"order":14,"title":"Can va can’t: imkoniyat va ruxsat","objective":"Qobiliyatni aytasiz, ruxsat so‘raysiz va sodda buyruq berasiz.","context":"Sinf loyiha uchun har kimning vazifasini taqsimlaydi.","prerequisites":["en-a1-13"],"minutes":25,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Can dan keyin fe’lning asosiy shakli keladi: She can draw. He cans yoki can to draw ishlatilmaydi.","Can’t qila olmaslik yoki ruxsat yo‘qligini bildiradi. Savolda can egadan oldin: Can you help?","Please + asosiy fe’l odobli oddiy buyruq. Don’t + fe’l taqiq. Can I …? bilan kundalik ruxsat so‘rash mumkin."],"pattern":"can + verb / Can I …? / Please … / Don’t …","examples":["I can draw a map.","She can speak English.","Can you help me?","We can’t use the computer now.","Please close the door.","Don’t touch the wet paint."],"vocabulary":[{"id":"en-a1-14-v0","term":"draw","meaning":"chizmoq","ipa":"/drɔː/","collocation":"draw a map","example":"I can draw a map."},{"id":"en-a1-14-v1","term":"paint","meaning":"bo‘yoq yoki bo‘yamoq","ipa":"/peɪnt/","collocation":"wet paint","example":"Don’t touch the wet paint."},{"id":"en-a1-14-v2","term":"touch","meaning":"tegmoq","ipa":"/tʌtʃ/","collocation":"touch the paint","example":"Don’t touch the wet paint."},{"id":"en-a1-14-v3","term":"close","meaning":"yopmoq","ipa":"/kləʊz/","collocation":"close the door","example":"Please close the door."}],"visuals":[{"kind":"sentence","title":"Ma’no va tuzilish","items":["can + verb / Can I …? / Please … / Don’t …","I can draw a map.","She can speak English."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Sinf loyiha uchun har kimning vazifasini taqsimlaydi.","Can you help me?","Please close the door."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"We can’t use the computer now.","audio":"/english-course/v7.23/en-a1-14-dictation.mp3"},"exercises":[{"id":"en-a1-14-choice","type":"choice","skill":"grammar","prompt":"Ruxsat so‘rang.","answers":["Can I open the window?"],"explanation":"Can I …? ruxsat savoli.","hint":"can + verb / Can I …? / Please … / Don’t …","options":["Can I open the window?","I can window open?","Does can I open?"]},{"id":"en-a1-14-gap","type":"grammarFill","skill":"grammar","prompt":"She can ___ English. (speak)","answers":["speak"],"explanation":"Can dan keyin fe’lning asosiy shakli keladi: She can draw. He cans yoki can to draw ishlatilmaydi. Can’t qila olmaslik yoki ruxsat yo‘qligini bildiradi. Savolda can egadan oldin: Can you help? Please + asosiy fe’l odobli oddiy buyruq. Don’t + fe’l taqiq. Can I …? bilan kundalik ruxsat so‘rash mumkin.","hint":"can + verb / Can I …? / Please … / Don’t …"},{"id":"en-a1-14-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["I can draw a map."],"explanation":"Can dan keyin fe’lning asosiy shakli keladi: She can draw. He cans yoki can to draw ishlatilmaydi. Can’t qila olmaslik yoki ruxsat yo‘qligini bildiradi. Savolda can egadan oldin: Can you help? Please + asosiy fe’l odobli oddiy buyruq. Don’t + fe’l taqiq. Can I …? bilan kundalik ruxsat so‘rash mumkin.","hint":"can + verb / Can I …? / Please … / Don’t …","tokens":["I","can","draw","a","map."]},{"id":"en-a1-14-fix","type":"correction","skill":"grammar","prompt":"He cans draw.","answers":["He can draw."],"explanation":"Can dan keyin fe’lning asosiy shakli keladi: She can draw. He cans yoki can to draw ishlatilmaydi. Can’t qila olmaslik yoki ruxsat yo‘qligini bildiradi. Savolda can egadan oldin: Can you help? Please + asosiy fe’l odobli oddiy buyruq. Don’t + fe’l taqiq. Can I …? bilan kundalik ruxsat so‘rash mumkin.","hint":"can + verb / Can I …? / Please … / Don’t …"},{"id":"en-a1-14-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["chizmoq","bo‘yoq yoki bo‘yamoq","tegmoq","yopmoq"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"can + verb / Can I …? / Please … / Don’t …","left":["draw","paint","touch","close"],"options":["chizmoq","bo‘yoq yoki bo‘yamoq","tegmoq","yopmoq"]}],"reading":{"title":"Can va can’t: imkoniyat va ruxsat — vaziyat","text":"The class is making a map of the school. Lola can draw, and Ali can write clear labels. Aziz can take photos. They can’t use the computer now because another group is using it. The teacher says, “Please work on paper first. Don’t touch the wet paint.” Lola asks, “Can I open the window?” The teacher says yes because the room is warm.","sentences":["The class is making a map of the school.","Lola can draw, and Ali can write clear labels.","Aziz can take photos.","They can’t use the computer now because another group is using it.","The teacher says, “Please work on paper first.","Don’t touch the wet paint.","” Lola asks, “Can I open the window?","” The teacher says yes because the room is warm."],"questions":[{"id":"en-a1-14-reading0","type":"choice","skill":"reading","prompt":"Aziz nima qila oladi?","answers":["take photos"],"explanation":"Aziz can take photos.","hint":"can + verb / Can I …? / Please … / Don’t …","options":["take photos","draw labels","use the computer now"]},{"id":"en-a1-14-reading1","type":"choice","skill":"reading","prompt":"Kompyuterni nega ishlata olmaydi?","answers":["another group is using it"],"explanation":"Because another group is using it.","hint":"can + verb / Can I …? / Please … / Don’t …","options":["another group is using it","it is broken","they cannot type"]},{"id":"en-a1-14-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"can + verb / Can I …? / Please … / Don’t …","options":["The class is making a map of the school.","Lola can draw, and Ali can write clear labels.","Aziz can take photos.","They can’t use the computer now because another group is using it.","The teacher says, “Please work on paper first.","Don’t touch the wet paint.","” Lola asks, “Can I open the window?","” The teacher says yes because the room is warm."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"Lola can draw our map. Ali can write the labels. Aziz can take photos. Please work on paper. Don’t touch the wet paint. You can use the computer after lunch.","audio":"/english-course/v7.23/en-a1-14.mp3","synthetic":true,"questions":[{"id":"en-a1-14-listening0","type":"choice","skill":"listening","prompt":"Yorliqlarni kim yozadi?","answers":["Ali"],"explanation":"Ali can write the labels.","hint":"can + verb / Can I …? / Please … / Don’t …","options":["Ali","Aziz","Lola"]},{"id":"en-a1-14-listening1","type":"choice","skill":"listening","prompt":"Kompyuterdan qachon foydalanish mumkin?","answers":["after lunch"],"explanation":"After lunch deyiladi.","hint":"can + verb / Can I …? / Please … / Don’t …","options":["after lunch","now","before school"]},{"id":"en-a1-14-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["Lola","after lunch"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"can + verb / Can I …? / Please … / Don’t …","rows":["Chizadigan o‘quvchi","Kompyuter vaqti"]},{"id":"en-a1-14-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["We can’t use the computer now."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"can + verb / Can I …? / Please … / Don’t …","audio":"/english-course/v7.23/en-a1-14-dictation.mp3","transcript":"We can’t use the computer now."}]},"writing":{"task":"Loyiha jamoasi uchun kim nima qila olishini va bitta taqiqni yozing.","audience":"Sinfdagi sherigingiz","minWords":30,"maxWords":90,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"Lola can draw a map. Ali can write clear labels, and I can take photos. We can’t use the computer now. Please bring paper and pens. Don’t touch the paint before it is dry.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["I can draw a map.","She can speak English.","Can you help me?"],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Qobiliyatlarni so‘rang va vazifalarni taqsimlang. Bitta ruxsat so‘rang.","seconds":35,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Loyiha jamoasi uchun kim nima qila olishini va bitta taqiqni yozing.","exit":[[{"id":"en-a1-14-exit0","type":"grammarFill","skill":"grammar","prompt":"She ___ draw. (qila oladi)","answers":["can"],"explanation":"Can dan keyin fe’lning asosiy shakli keladi: She can draw. He cans yoki can to draw ishlatilmaydi. Can’t qila olmaslik yoki ruxsat yo‘qligini bildiradi. Savolda can egadan oldin: Can you help? Please + asosiy fe’l odobli oddiy buyruq. Don’t + fe’l taqiq. Can I …? bilan kundalik ruxsat so‘rash mumkin.","hint":"can + verb / Can I …? / Please … / Don’t …"},{"id":"en-a1-14-exit1","type":"grammarFill","skill":"grammar","prompt":"Don’t ___ the paint.","answers":["touch"],"explanation":"Can dan keyin fe’lning asosiy shakli keladi: She can draw. He cans yoki can to draw ishlatilmaydi. Can’t qila olmaslik yoki ruxsat yo‘qligini bildiradi. Savolda can egadan oldin: Can you help? Please + asosiy fe’l odobli oddiy buyruq. Don’t + fe’l taqiq. Can I …? bilan kundalik ruxsat so‘rash mumkin.","hint":"can + verb / Can I …? / Please … / Don’t …"},{"id":"en-a1-14-exit2","type":"grammarFill","skill":"grammar","prompt":"Can you ___ me?","answers":["help"],"explanation":"Can dan keyin fe’lning asosiy shakli keladi: She can draw. He cans yoki can to draw ishlatilmaydi. Can’t qila olmaslik yoki ruxsat yo‘qligini bildiradi. Savolda can egadan oldin: Can you help? Please + asosiy fe’l odobli oddiy buyruq. Don’t + fe’l taqiq. Can I …? bilan kundalik ruxsat so‘rash mumkin.","hint":"can + verb / Can I …? / Please … / Don’t …"},{"id":"en-a1-14-exit3","type":"choice","skill":"grammar","prompt":"Can dan keyin qaysi shakl?","answers":["the base verb"],"explanation":"Can fe’l shaklini o‘zgartirmaydi.","hint":"can + verb / Can I …? / Please … / Don’t …","options":["the base verb","verb + s","to + verb"]},{"id":"en-a1-14-exit4","type":"choice","skill":"grammar","prompt":"Odobli buyruqni tanlang.","answers":["Please close the door."],"explanation":"Please buyruqni yumshatadi.","hint":"can + verb / Can I …? / Please … / Don’t …","options":["Please close the door.","You close? does","Can to close."]}],[{"id":"en-a1-14-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["She can speak English."],"explanation":"Can dan keyin fe’lning asosiy shakli keladi: She can draw. He cans yoki can to draw ishlatilmaydi. Can’t qila olmaslik yoki ruxsat yo‘qligini bildiradi. Savolda can egadan oldin: Can you help? Please + asosiy fe’l odobli oddiy buyruq. Don’t + fe’l taqiq. Can I …? bilan kundalik ruxsat so‘rash mumkin.","hint":"can + verb / Can I …? / Please … / Don’t …","tokens":["She","can","speak","English."]},{"id":"en-a1-14-exit-b1","type":"grammarFill","skill":"grammar","prompt":"Don’t ___ the paint.","answers":["touch"],"explanation":"Can dan keyin fe’lning asosiy shakli keladi: She can draw. He cans yoki can to draw ishlatilmaydi. Can’t qila olmaslik yoki ruxsat yo‘qligini bildiradi. Savolda can egadan oldin: Can you help? Please + asosiy fe’l odobli oddiy buyruq. Don’t + fe’l taqiq. Can I …? bilan kundalik ruxsat so‘rash mumkin.","hint":"can + verb / Can I …? / Please … / Don’t …"},{"id":"en-a1-14-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["We can’t use the computer now."],"explanation":"Can dan keyin fe’lning asosiy shakli keladi: She can draw. He cans yoki can to draw ishlatilmaydi. Can’t qila olmaslik yoki ruxsat yo‘qligini bildiradi. Savolda can egadan oldin: Can you help? Please + asosiy fe’l odobli oddiy buyruq. Don’t + fe’l taqiq. Can I …? bilan kundalik ruxsat so‘rash mumkin.","hint":"can + verb / Can I …? / Please … / Don’t …","tokens":["We","can’t","use","the","computer","now."]},{"id":"en-a1-14-exit-b3","type":"choice","skill":"grammar","prompt":"Can dan keyin qaysi shakl?","answers":["the base verb"],"explanation":"Can fe’l shaklini o‘zgartirmaydi.","hint":"can + verb / Can I …? / Please … / Don’t …","options":["the base verb","verb + s","to + verb"]},{"id":"en-a1-14-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Don’t touch the wet paint."],"explanation":"Can dan keyin fe’lning asosiy shakli keladi: She can draw. He cans yoki can to draw ishlatilmaydi. Can’t qila olmaslik yoki ruxsat yo‘qligini bildiradi. Savolda can egadan oldin: Can you help? Please + asosiy fe’l odobli oddiy buyruq. Don’t + fe’l taqiq. Can I …? bilan kundalik ruxsat so‘rash mumkin.","hint":"can + verb / Can I …? / Please … / Don’t …","tokens":["Don’t","touch","the","wet","paint."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-a1-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-a1-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-a1-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-a1-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-a1-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-a1-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-a1-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-a1-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a1-15','en-a1-15',null,1,15,'published',1,'{"id":"en-a1-15","baseId":"en-a1-15","revision":1,"level":"A1","levelIndex":1,"order":15,"title":"Joy va vaqt predloglari","objective":"In, on, at, under, between bilan joy va vaqtni aniqlashtirasiz.","context":"Sinfdoshingiz uchrashuv joyini topishi kerak.","prerequisites":["en-a1-14"],"minutes":25,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Joyda in ichida, on sirtida, under ostida, between ikki narsa orasida degani. At ma’lum nuqta yoki faoliyat joyini bildirishi mumkin.","Vaqtda in oy/yil va ko‘pincha kun qismi; on kun/sana; at soat uchun: in May, on Monday, at five.","In the morning, lekin at night; ayrim birikmalarni butun holda o‘rganamiz. Predlog o‘zbekcha bir qo‘shimchaga doim aynan mos kelmaydi."],"pattern":"in May / on Monday / at five; on the desk / under the desk","examples":["The book is on the desk.","The bag is under the chair.","The café is between two shops.","We meet on Monday.","The lesson starts at five.","I read in the morning."],"vocabulary":[{"id":"en-a1-15-v0","term":"under","meaning":"ostida","ipa":"/ˈʌndə/","collocation":"under the chair","example":"The bag is under the chair."},{"id":"en-a1-15-v1","term":"between","meaning":"orasida","ipa":"/bɪˈtwiːn/","collocation":"between two shops","example":"The café is between two shops."},{"id":"en-a1-15-v2","term":"morning","meaning":"ertalab","ipa":"/ˈmɔːnɪŋ/","collocation":"in the morning","example":"I read in the morning."},{"id":"en-a1-15-v3","term":"meet","meaning":"uchrashmoq","ipa":"/miːt/","collocation":"meet at five","example":"We meet on Monday."}],"visuals":[{"kind":"preposition","title":"Ma’no va tuzilish","items":["in May / on Monday / at five; on the desk / under the desk","The book is on the desk.","The bag is under the chair."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Sinfdoshingiz uchrashuv joyini topishi kerak.","The café is between two shops.","The lesson starts at five."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"We meet on Monday.","audio":"/english-course/v7.23/en-a1-15-dictation.mp3"},"exercises":[{"id":"en-a1-15-choice","type":"choice","skill":"grammar","prompt":"Kitob stol sirtida. Qaysi predlog?","answers":["on"],"explanation":"On sirt bilan aloqa.","hint":"in May / on Monday / at five; on the desk / under the desk","options":["on","under","between"]},{"id":"en-a1-15-gap","type":"grammarFill","skill":"grammar","prompt":"The lesson starts ___ five.","answers":["at"],"explanation":"Joyda in ichida, on sirtida, under ostida, between ikki narsa orasida degani. At ma’lum nuqta yoki faoliyat joyini bildirishi mumkin. Vaqtda in oy/yil va ko‘pincha kun qismi; on kun/sana; at soat uchun: in May, on Monday, at five. In the morning, lekin at night; ayrim birikmalarni butun holda o‘rganamiz. Predlog o‘zbekcha bir qo‘shimchaga doim aynan mos kelmaydi.","hint":"in May / on Monday / at five; on the desk / under the desk"},{"id":"en-a1-15-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["The book is on the desk."],"explanation":"Joyda in ichida, on sirtida, under ostida, between ikki narsa orasida degani. At ma’lum nuqta yoki faoliyat joyini bildirishi mumkin. Vaqtda in oy/yil va ko‘pincha kun qismi; on kun/sana; at soat uchun: in May, on Monday, at five. In the morning, lekin at night; ayrim birikmalarni butun holda o‘rganamiz. Predlog o‘zbekcha bir qo‘shimchaga doim aynan mos kelmaydi.","hint":"in May / on Monday / at five; on the desk / under the desk","tokens":["The","book","is","on","the","desk."]},{"id":"en-a1-15-fix","type":"correction","skill":"grammar","prompt":"We meet in Monday.","answers":["We meet on Monday."],"explanation":"Joyda in ichida, on sirtida, under ostida, between ikki narsa orasida degani. At ma’lum nuqta yoki faoliyat joyini bildirishi mumkin. Vaqtda in oy/yil va ko‘pincha kun qismi; on kun/sana; at soat uchun: in May, on Monday, at five. In the morning, lekin at night; ayrim birikmalarni butun holda o‘rganamiz. Predlog o‘zbekcha bir qo‘shimchaga doim aynan mos kelmaydi.","hint":"in May / on Monday / at five; on the desk / under the desk"},{"id":"en-a1-15-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["ostida","orasida","ertalab","uchrashmoq"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"in May / on Monday / at five; on the desk / under the desk","left":["under","between","morning","meet"],"options":["ostida","orasida","ertalab","uchrashmoq"]},{"id":"en-a1-15-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["under","between","morning","meet"],"options":["under the chair","between two shops","in the morning","meet at five"],"answers":["under the chair","between two shops","in the morning","meet at five"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."}],"reading":{"title":"Joy va vaqt predloglari — vaziyat","text":"We meet at the small café on Monday at five. The café is between a bookshop and a bakery. Inside, our table is near the window. Lola’s bag is under her chair, and her notebook is on the table. We usually study in the morning, but this week we meet after school. Ali arrives at five and finds us easily because Lola sent him a simple map.","sentences":["We meet at the small café on Monday at five.","The café is between a bookshop and a bakery.","Inside, our table is near the window.","Lola’s bag is under her chair, and her notebook is on the table.","We usually study in the morning, but this week we meet after school.","Ali arrives at five and finds us easily because Lola sent him a simple map."],"questions":[{"id":"en-a1-15-reading0","type":"choice","skill":"reading","prompt":"Uchrashuv soati qaysi?","answers":["five"],"explanation":"At five aniq vaqtni bildiradi.","hint":"in May / on Monday / at five; on the desk / under the desk","options":["five","four","six"]},{"id":"en-a1-15-reading1","type":"choice","skill":"reading","prompt":"Sumka qayerda?","answers":["under the chair"],"explanation":"Lola’s bag is under her chair.","hint":"in May / on Monday / at five; on the desk / under the desk","options":["under the chair","on the table","between the shops"]},{"id":"en-a1-15-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"in May / on Monday / at five; on the desk / under the desk","options":["We meet at the small café on Monday at five.","The café is between a bookshop and a bakery.","Inside, our table is near the window.","Lola’s bag is under her chair, and her notebook is on the table.","We usually study in the morning, but this week we meet after school.","Ali arrives at five and finds us easily because Lola sent him a simple map."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"Meet me on Monday at five. The café is between the bookshop and the bakery. Our table is near the window. My notebook is on the table, and my bag is under the chair.","audio":"/english-course/v7.23/en-a1-15.mp3","synthetic":true,"questions":[{"id":"en-a1-15-listening0","type":"choice","skill":"listening","prompt":"Uchrashuv kuni qaysi?","answers":["Monday"],"explanation":"On Monday — hafta kuni.","hint":"in May / on Monday / at five; on the desk / under the desk","options":["Monday","May","Friday"]},{"id":"en-a1-15-listening1","type":"choice","skill":"listening","prompt":"Daftar qayerda?","answers":["on the table"],"explanation":"My notebook is on the table.","hint":"in May / on Monday / at five; on the desk / under the desk","options":["on the table","under the chair","in the bakery"]},{"id":"en-a1-15-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["Monday","five"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"in May / on Monday / at five; on the desk / under the desk","rows":["Kun","Soat"]},{"id":"en-a1-15-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["We meet on Monday."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"in May / on Monday / at five; on the desk / under the desk","audio":"/english-course/v7.23/en-a1-15-dictation.mp3","transcript":"We meet on Monday."}]},"writing":{"task":"Do‘stingiz uchun joyi va vaqti aniq uchrashuv xabari yozing.","audience":"Sinfdagi sherigingiz","minWords":30,"maxWords":90,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"Please meet me on Friday at four. The library is between the school and the park. I am sitting near the window. My blue bag is under the table, and our books are on it.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["The book is on the desk.","The bag is under the chair.","The café is between two shops."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Xona xaritasini va uchrashuv vaqtini predloglar bilan tasvirlang.","seconds":35,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Do‘stingiz uchun joyi va vaqti aniq uchrashuv xabari yozing.","exit":[[{"id":"en-a1-15-exit0","type":"grammarFill","skill":"grammar","prompt":"___ the morning","answers":["in"],"explanation":"Joyda in ichida, on sirtida, under ostida, between ikki narsa orasida degani. At ma’lum nuqta yoki faoliyat joyini bildirishi mumkin. Vaqtda in oy/yil va ko‘pincha kun qismi; on kun/sana; at soat uchun: in May, on Monday, at five. In the morning, lekin at night; ayrim birikmalarni butun holda o‘rganamiz. Predlog o‘zbekcha bir qo‘shimchaga doim aynan mos kelmaydi.","hint":"in May / on Monday / at five; on the desk / under the desk"},{"id":"en-a1-15-exit1","type":"grammarFill","skill":"grammar","prompt":"___ Monday","answers":["on"],"explanation":"Joyda in ichida, on sirtida, under ostida, between ikki narsa orasida degani. At ma’lum nuqta yoki faoliyat joyini bildirishi mumkin. Vaqtda in oy/yil va ko‘pincha kun qismi; on kun/sana; at soat uchun: in May, on Monday, at five. In the morning, lekin at night; ayrim birikmalarni butun holda o‘rganamiz. Predlog o‘zbekcha bir qo‘shimchaga doim aynan mos kelmaydi.","hint":"in May / on Monday / at five; on the desk / under the desk"},{"id":"en-a1-15-exit2","type":"grammarFill","skill":"grammar","prompt":"___ five o’clock","answers":["at"],"explanation":"Joyda in ichida, on sirtida, under ostida, between ikki narsa orasida degani. At ma’lum nuqta yoki faoliyat joyini bildirishi mumkin. Vaqtda in oy/yil va ko‘pincha kun qismi; on kun/sana; at soat uchun: in May, on Monday, at five. In the morning, lekin at night; ayrim birikmalarni butun holda o‘rganamiz. Predlog o‘zbekcha bir qo‘shimchaga doim aynan mos kelmaydi.","hint":"in May / on Monday / at five; on the desk / under the desk"},{"id":"en-a1-15-exit3","type":"choice","skill":"grammar","prompt":"Under nimani bildiradi?","answers":["below something"],"explanation":"Under ostidagi joy.","hint":"in May / on Monday / at five; on the desk / under the desk","options":["below something","inside something","between two things"]},{"id":"en-a1-15-exit4","type":"choice","skill":"grammar","prompt":"In May to‘g‘rimi?","answers":["Yes"],"explanation":"Oy uchun in.","hint":"in May / on Monday / at five; on the desk / under the desk","options":["Yes","No","Only with a clock"]}],[{"id":"en-a1-15-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The bag is under the chair."],"explanation":"Joyda in ichida, on sirtida, under ostida, between ikki narsa orasida degani. At ma’lum nuqta yoki faoliyat joyini bildirishi mumkin. Vaqtda in oy/yil va ko‘pincha kun qismi; on kun/sana; at soat uchun: in May, on Monday, at five. In the morning, lekin at night; ayrim birikmalarni butun holda o‘rganamiz. Predlog o‘zbekcha bir qo‘shimchaga doim aynan mos kelmaydi.","hint":"in May / on Monday / at five; on the desk / under the desk","tokens":["The","bag","is","under","the","chair."]},{"id":"en-a1-15-exit-b1","type":"grammarFill","skill":"grammar","prompt":"___ Monday","answers":["on"],"explanation":"Joyda in ichida, on sirtida, under ostida, between ikki narsa orasida degani. At ma’lum nuqta yoki faoliyat joyini bildirishi mumkin. Vaqtda in oy/yil va ko‘pincha kun qismi; on kun/sana; at soat uchun: in May, on Monday, at five. In the morning, lekin at night; ayrim birikmalarni butun holda o‘rganamiz. Predlog o‘zbekcha bir qo‘shimchaga doim aynan mos kelmaydi.","hint":"in May / on Monday / at five; on the desk / under the desk"},{"id":"en-a1-15-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["We meet on Monday."],"explanation":"Joyda in ichida, on sirtida, under ostida, between ikki narsa orasida degani. At ma’lum nuqta yoki faoliyat joyini bildirishi mumkin. Vaqtda in oy/yil va ko‘pincha kun qismi; on kun/sana; at soat uchun: in May, on Monday, at five. In the morning, lekin at night; ayrim birikmalarni butun holda o‘rganamiz. Predlog o‘zbekcha bir qo‘shimchaga doim aynan mos kelmaydi.","hint":"in May / on Monday / at five; on the desk / under the desk","tokens":["We","meet","on","Monday."]},{"id":"en-a1-15-exit-b3","type":"choice","skill":"grammar","prompt":"Under nimani bildiradi?","answers":["below something"],"explanation":"Under ostidagi joy.","hint":"in May / on Monday / at five; on the desk / under the desk","options":["below something","inside something","between two things"]},{"id":"en-a1-15-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["I read in the morning."],"explanation":"Joyda in ichida, on sirtida, under ostida, between ikki narsa orasida degani. At ma’lum nuqta yoki faoliyat joyini bildirishi mumkin. Vaqtda in oy/yil va ko‘pincha kun qismi; on kun/sana; at soat uchun: in May, on Monday, at five. In the morning, lekin at night; ayrim birikmalarni butun holda o‘rganamiz. Predlog o‘zbekcha bir qo‘shimchaga doim aynan mos kelmaydi.","hint":"in May / on Monday / at five; on the desk / under the desk","tokens":["I","read","in","the","morning."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-a1-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-a1-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-a1-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-a1-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-a1-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-a1-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-a1-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-a1-15","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a1-16','en-a1-16',null,1,16,'published',1,'{"id":"en-a1-16","baseId":"en-a1-16","revision":1,"level":"A1","levelIndex":1,"order":16,"title":"Qanchalik tez-tez? Frequency adverbs","objective":"Always, usually, often, sometimes, never bilan odat tezligini aytasiz.","context":"O‘quvchilar haftalik kitob o‘qish odatlarini solishtiradi.","prerequisites":["en-a1-15"],"minutes":25,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Always — doim, usually — odatda, often — tez-tez, sometimes — ba’zan, never — hech qachon. Bular aniq matematik foiz emas.","Asosiy fe’ldan oldin: I often read. To be dan keyin: She is always ready.","Never allaqachon inkor ma’nosida: I never go. Standart shaklda I don’t never go ishlatmang. Every day va twice a week aniq takror jadvalini bildiradi."],"pattern":"I often read. / She is always ready. / twice a week","examples":["I often read after school.","She is always ready.","We sometimes study together.","Ali never drinks coffee.","They play twice a week.","I usually go to bed at ten."],"vocabulary":[{"id":"en-a1-16-v0","term":"always","meaning":"doim","ipa":"/ˈɔːlweɪz/","collocation":"always ready","example":"She is always ready."},{"id":"en-a1-16-v1","term":"sometimes","meaning":"ba’zan","ipa":"/ˈsʌmtaɪmz/","collocation":"sometimes study","example":"We sometimes study together."},{"id":"en-a1-16-v2","term":"never","meaning":"hech qachon","ipa":"/ˈnevə/","collocation":"never drink coffee","example":"Ali never drinks coffee."},{"id":"en-a1-16-v3","term":"twice","meaning":"ikki marta","ipa":"/twaɪs/","collocation":"twice a week","example":"They play twice a week."}],"visuals":[{"kind":"frequency","title":"Ma’no va tuzilish","items":["I often read. / She is always ready. / twice a week","I often read after school.","She is always ready."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["O‘quvchilar haftalik kitob o‘qish odatlarini solishtiradi.","We sometimes study together.","They play twice a week."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"Ali never drinks coffee.","audio":"/english-course/v7.23/en-a1-16-dictation.mp3"},"exercises":[{"id":"en-a1-16-choice","type":"choice","skill":"grammar","prompt":"Often ning to‘g‘ri o‘rnini tanlang.","answers":["I often read."],"explanation":"Asosiy fe’ldan oldin eng odatiy joy.","hint":"I often read. / She is always ready. / twice a week","options":["I often read.","I read often books.","Often I am read."]},{"id":"en-a1-16-gap","type":"grammarFill","skill":"grammar","prompt":"She is ___ ready. (doim)","answers":["always"],"explanation":"Always — doim, usually — odatda, often — tez-tez, sometimes — ba’zan, never — hech qachon. Bular aniq matematik foiz emas. Asosiy fe’ldan oldin: I often read. To be dan keyin: She is always ready. Never allaqachon inkor ma’nosida: I never go. Standart shaklda I don’t never go ishlatmang. Every day va twice a week aniq takror jadvalini bildiradi.","hint":"I often read. / She is always ready. / twice a week"},{"id":"en-a1-16-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["I often read after school."],"explanation":"Always — doim, usually — odatda, often — tez-tez, sometimes — ba’zan, never — hech qachon. Bular aniq matematik foiz emas. Asosiy fe’ldan oldin: I often read. To be dan keyin: She is always ready. Never allaqachon inkor ma’nosida: I never go. Standart shaklda I don’t never go ishlatmang. Every day va twice a week aniq takror jadvalini bildiradi.","hint":"I often read. / She is always ready. / twice a week","tokens":["I","often","read","after","school."]},{"id":"en-a1-16-fix","type":"correction","skill":"grammar","prompt":"I don’t never drink coffee.","answers":["I never drink coffee."],"explanation":"Always — doim, usually — odatda, often — tez-tez, sometimes — ba’zan, never — hech qachon. Bular aniq matematik foiz emas. Asosiy fe’ldan oldin: I often read. To be dan keyin: She is always ready. Never allaqachon inkor ma’nosida: I never go. Standart shaklda I don’t never go ishlatmang. Every day va twice a week aniq takror jadvalini bildiradi.","hint":"I often read. / She is always ready. / twice a week"},{"id":"en-a1-16-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["doim","ba’zan","hech qachon","ikki marta"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"I often read. / She is always ready. / twice a week","left":["always","sometimes","never","twice"],"options":["doim","ba’zan","hech qachon","ikki marta"]},{"id":"en-a1-16-dialogue","type":"dialogue","skill":"grammar","prompt":"Sherik: “Can you give one example?” Siz: darsdagi birinchi namunani qayta tuzing.","answers":["I often read after school."],"tokens":["I","often","read","after","school."],"hint":"I often read. / She is always ready. / twice a week","explanation":"Always — doim, usually — odatda, often — tez-tez, sometimes — ba’zan, never — hech qachon. Bular aniq matematik foiz emas."},{"id":"en-a1-16-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Savol so‘zlari: kim, nima, qayer, qachon?: Sababni qaysi savol so‘raydi?","answers":["Why?"],"explanation":"Why sabab uchun.","hint":"Where is …? / When do you …? / Why …? — Because …","options":["Why?","Where?","When?"],"recap":true,"sourceLesson":"Savol so‘zlari: kim, nima, qayer, qachon?"},{"id":"en-a1-16-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Can va can’t: imkoniyat va ruxsat: Ruxsat so‘rang.","answers":["Can I open the window?"],"explanation":"Can I …? ruxsat savoli.","hint":"can + verb / Can I …? / Please … / Don’t …","options":["Can I open the window?","I can window open?","Does can I open?"],"recap":true,"sourceLesson":"Can va can’t: imkoniyat va ruxsat"},{"id":"en-a1-16-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Joy va vaqt predloglari: Kitob stol sirtida. Qaysi predlog?","answers":["on"],"explanation":"On sirt bilan aloqa.","hint":"in May / on Monday / at five; on the desk / under the desk","options":["on","under","between"],"recap":true,"sourceLesson":"Joy va vaqt predloglari"}],"reading":{"title":"Qanchalik tez-tez? Frequency adverbs — vaziyat","text":"Lola usually reads after dinner. She is always ready for the reading club. Ali often reads science books, but he sometimes reads comics too. They study together twice a week. Aziz never drinks coffee in the evening. He usually goes to bed at ten. These are their habits, but a special event can change their routine. Today, they are staying later for a school project.","sentences":["Lola usually reads after dinner.","She is always ready for the reading club.","Ali often reads science books, but he sometimes reads comics too.","They study together twice a week.","Aziz never drinks coffee in the evening.","He usually goes to bed at ten.","These are their habits, but a special event can change their routine.","Today, they are staying later for a school project."],"questions":[{"id":"en-a1-16-reading0","type":"choice","skill":"reading","prompt":"Birga haftasiga necha marta o‘qishadi?","answers":["twice"],"explanation":"Twice a week — ikki marta.","hint":"I often read. / She is always ready. / twice a week","options":["twice","once","every day"]},{"id":"en-a1-16-reading1","type":"choice","skill":"reading","prompt":"Aziz kechqurun nima ichmaydi?","answers":["coffee"],"explanation":"Never drinks coffee deyiladi.","hint":"I often read. / She is always ready. / twice a week","options":["coffee","water","tea"]},{"id":"en-a1-16-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"I often read. / She is always ready. / twice a week","options":["Lola usually reads after dinner.","She is always ready for the reading club.","Ali often reads science books, but he sometimes reads comics too.","They study together twice a week.","Aziz never drinks coffee in the evening.","He usually goes to bed at ten.","These are their habits, but a special event can change their routine.","Today, they are staying later for a school project."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"We study together twice a week. Lola is always ready. I often read science books and sometimes read comics. I never drink coffee in the evening.","audio":"/english-course/v7.23/en-a1-16.mp3","synthetic":true,"questions":[{"id":"en-a1-16-listening0","type":"choice","skill":"listening","prompt":"Lola qanday?","answers":["always ready"],"explanation":"Is always ready — to be dan keyin.","hint":"I often read. / She is always ready. / twice a week","options":["always ready","never ready","often late"]},{"id":"en-a1-16-listening1","type":"choice","skill":"listening","prompt":"Komiks qanchalik tez-tez?","answers":["sometimes"],"explanation":"Sometimes read comics deyiladi.","hint":"I often read. / She is always ready. / twice a week","options":["sometimes","always","never"]},{"id":"en-a1-16-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["twice a week","sometimes"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"I often read. / She is always ready. / twice a week","rows":["Birgalikdagi o‘qish","Komiks"]},{"id":"en-a1-16-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["Ali never drinks coffee."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"I often read. / She is always ready. / twice a week","audio":"/english-course/v7.23/en-a1-16-dictation.mp3","transcript":"Ali never drinks coffee."}]},"writing":{"task":"O‘qish odatlaringizni beshta turli tezlik ifodasi bilan yozing.","audience":"Sinfdagi sherigingiz","minWords":30,"maxWords":90,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"I usually read after dinner. I often write new words in my notebook. I sometimes study with friends. I am always ready for our Friday club. I never leave my books on the bus.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["I often read after school.","She is always ready.","We sometimes study together."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"How often …? savoli bilan sherigingizning uch odatini bilib oling.","seconds":35,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"O‘qish odatlaringizni beshta turli tezlik ifodasi bilan yozing.","exit":[[{"id":"en-a1-16-exit0","type":"grammarFill","skill":"grammar","prompt":"Ikki marta haftasiga: ___ a week","answers":["twice"],"explanation":"Always — doim, usually — odatda, often — tez-tez, sometimes — ba’zan, never — hech qachon. Bular aniq matematik foiz emas. Asosiy fe’ldan oldin: I often read. To be dan keyin: She is always ready. Never allaqachon inkor ma’nosida: I never go. Standart shaklda I don’t never go ishlatmang. Every day va twice a week aniq takror jadvalini bildiradi.","hint":"I often read. / She is always ready. / twice a week"},{"id":"en-a1-16-exit1","type":"grammarFill","skill":"grammar","prompt":"She ___ always ready.","answers":["is"],"explanation":"Always — doim, usually — odatda, often — tez-tez, sometimes — ba’zan, never — hech qachon. Bular aniq matematik foiz emas. Asosiy fe’ldan oldin: I often read. To be dan keyin: She is always ready. Never allaqachon inkor ma’nosida: I never go. Standart shaklda I don’t never go ishlatmang. Every day va twice a week aniq takror jadvalini bildiradi.","hint":"I often read. / She is always ready. / twice a week"},{"id":"en-a1-16-exit2","type":"grammarFill","skill":"grammar","prompt":"I ___ drink coffee. (hech qachon)","answers":["never"],"explanation":"Always — doim, usually — odatda, often — tez-tez, sometimes — ba’zan, never — hech qachon. Bular aniq matematik foiz emas. Asosiy fe’ldan oldin: I often read. To be dan keyin: She is always ready. Never allaqachon inkor ma’nosida: I never go. Standart shaklda I don’t never go ishlatmang. Every day va twice a week aniq takror jadvalini bildiradi.","hint":"I often read. / She is always ready. / twice a week"},{"id":"en-a1-16-exit3","type":"choice","skill":"grammar","prompt":"Frequency adverb har doim aniq foizmi?","answers":["No"],"explanation":"Bular kontekstga bog‘liq umumiy tezlik ifodasi.","hint":"I often read. / She is always ready. / twice a week","options":["No","Yes","Only always"]},{"id":"en-a1-16-exit4","type":"choice","skill":"grammar","prompt":"Odatni tanlang.","answers":["I usually read after dinner."],"explanation":"Usually oddiy hozirgi zamon bilan odatni ko‘rsatadi.","hint":"I often read. / She is always ready. / twice a week","options":["I usually read after dinner.","I am usually read.","I usually reading."]}],[{"id":"en-a1-16-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["She is always ready."],"expl