stions":[{"id":"en-a1-16-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Savol so‘zlari: kim, nima, qayer, qachon?: Sababni qaysi savol so‘raydi?","answers":["Why?"],"explanation":"Why sabab uchun.","hint":"Where is …? / When do you …? / Why …? — Because …","options":["Why?","Where?","When?"],"recap":true,"sourceLesson":"Savol so‘zlari: kim, nima, qayer, qachon?"},{"id":"en-a1-16-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Can va can’t: imkoniyat va ruxsat: Ruxsat so‘rang.","answers":["Can I open the window?"],"explanation":"Can I …? ruxsat savoli.","hint":"can + verb / Can I …? / Please … / Don’t …","options":["Can I open the window?","I can window open?","Does can I open?"],"recap":true,"sourceLesson":"Can va can’t: imkoniyat va ruxsat"},{"id":"en-a1-16-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Joy va vaqt predloglari: Kitob stol sirtida. Qaysi predlog?","answers":["on"],"explanation":"On sirt bilan aloqa.","hint":"in May / on Monday / at five; on the desk / under the desk","options":["on","under","between"],"recap":true,"sourceLesson":"Joy va vaqt predloglari"}]}'::jsonb) on conflict(id,revision) do nothing;
